/// <summary>
/// Extension of method modified
/// </summary>
public void modified()
{
    next modified();

    this.avaRefreshCallerUI();
}

/// <summary>
/// Researches and refreshes caller formDataSource and UI
/// </summary>
public void avaRefreshCallerUI()
{
    FormDataSource fds = element.AVASpecialDiscSalesLine_ds;

    fds.research(true);
    fds.refresh();

    fds = element.salesLine_ds;

    fds.research(true);
    fds.refresh();
}
